import re
from taf.selenium.gnb.oam.coam.cu.facade import (Coam, Coam21B, Coam22R1, Coam22R2, Coam22R3,
                                                 Coam22R4, Coam23R4, Coam24R2, Coam24R3, Coam25R1, Coam25R2,
                                                 Coam25R3, Coam26R1)
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SupportedCoams(object):
    coam = Coam
    coam21b = Coam21B
    coam22r1 = Coam22R1
    coam22r2 = Coam22R2
    coam22r3 = Coam22R3
    coam22r4 = Coam22R4
    coam23r4 = Coam23R4
    coam24r2 = Coam24R2
    coam24r3 = Coam24R3
    coam25r1 = Coam25R1
    coam25r2 = Coam25R2
    coam25r3 = Coam25R3
    coam26r1 = Coam26R1


class Provider:
    default_version = 'coam26r1'

    @classmethod
    def provide(cls, version=None):
        """
        Provides the appropriate COAM version. Falls back to previous minor in same major,
        or highest previous major version, or finally to default.
        """
        requested_version = cls.parse_version(version) or cls.default_version

        if hasattr(SupportedCoams, requested_version):
            return getattr(SupportedCoams, requested_version)

        supported_versions = cls.get_supported_versions()

        req_major, req_minor = cls.extract_major_minor(requested_version)

        fallback = cls.find_fallback(supported_versions, lambda v: v[0] == req_major and v[1] < req_minor)
        if fallback:
            logger.warning(
                f"Unsupported version: {requested_version}. "
                f"Falling back to the previous minor version: {fallback}. "
                "Some keywords may behave differently."
            )
            return getattr(SupportedCoams, fallback)

        fallback = cls.find_fallback(supported_versions, lambda v: v[0] < req_major)
        if fallback:
            logger.warning(
                f"Unsupported version: {requested_version}. "
                f"Falling back to the previous major version: {fallback}. "
                "Some keywords may behave differently."
            )
            return getattr(SupportedCoams, fallback)

        logger.warning(
            f"Unsupported version: {requested_version}. "
            f"Falling back to the default version: {cls.default_version}. "
            "Some keywords may behave differently."
        )
        return getattr(SupportedCoams, cls.default_version)

    @staticmethod
    def parse_version(version):
        if not version:
            return None
        version = version.strip()
        match = re.match(r"^coam(\d+)r(\d+)$", version, re.IGNORECASE)
        if match:
            major, minor = match.groups()
            return f"coam{int(major)}r{int(minor)}"
        logger.warning(f"Invalid version format: {version}.")
        return None

    @staticmethod
    def extract_major_minor(version_str):
        match = re.match(r"coam(\d+)r(\d+)", version_str)
        return (int(match.group(1)), int(match.group(2))) if match else (0, 0)

    @staticmethod
    def get_supported_versions():
        versions = []
        for attr in dir(SupportedCoams):
            if attr.startswith("coam"):
                m = re.match(r"coam(\d+)r(\d+)", attr)
                if m:
                    major, minor = int(m.group(1)), int(m.group(2))
                    versions.append((major, minor, attr))
        return sorted(versions)

    @staticmethod
    def find_fallback(versions, condition):
        candidates = [v for v in versions if condition(v)]
        return candidates[-1][2] if candidates else None
